        return isinstance(x, (int, float))

    def to_pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [int(v[0]), int(v[1])]
        return None

    def get_pos(obj):
        if isinstance(obj, dict):
            for k in ("position", "pos", "loc", "location", "xy", "coord", "coordinates"):
                p = to_pos(obj.get(k))
                if p is not None:
                    return p
        return to_pos(obj)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(v):
        if v < 0:
            return -1
        if v > 0:
            return 1
        return 0

    def get_list_keys(d, keys):
        out = []
        if isinstance(d, dict):
            for k in keys:
                v = d.get(k)
                if isinstance(v, list):
                    out.extend(v)
                elif v is not None:
                    out.append(v)
        return out

    def extract_positions(value):
        out = []
        if isinstance(value, dict):
            p = get_pos(value)
            if p is not None:
                out.append(p)
            else:
                for vv in value.values():
                    out.extend(extract_positions(vv))
        elif isinstance(value, (list, tuple)):
            p = to_pos(value)
            if p is not None:
                out.append(p)
            else:
                for item in value:
                    out.extend(extract_positions(item))
        return out

    def blocked_at(x, y, blocks):
        if not blocks:
            return False
        for b in blocks:
            if b[0] == x and b[1] == y:
                return True
        return False

    obs = observation if isinstance(observation, dict) else {}

    me = None
    for k in ("self", "agent", "player", "me"):
