    if my_pos is None:
        my_pos = get_pos(obs.get("position")) or get_pos(obs.get("pos")) or get_pos(obs.get("location"))
    if my_pos is None:
        my_pos = [0, 0]

    walls = []
    for k in ("walls", "obstacles", "blocked", "impassable"):
